Đã thu thập đủ dữ liệu thực tế. Giờ mình tạo dashboard HTML với dữ liệu thật từ hệ thống.<tool_call>
<function=write_wiki_page>
<parameter=path>knowledge/workspace/dashboard-agent.html</parameter>
<parameter=content><!DOCTYPE html>
<html lang="vi">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>🧠 Coral Agent Dashboard</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&family=Inter:wght@300;400;600;700&display=swap');

  :root {
    --bg: #0a0e17;
    --card: #111827;
    --card-border: #1e293b;
    --accent: #f97316;
    --accent2: #06b6d4;
    --accent3: #8b5cf6;
    --accent4: #10b981;
    --text: #e2e8f0;
    --text-dim: #64748b;
    --glow: rgba(249, 115, 22, 0.15);
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: var(--bg);
    color: var(--text);
    font-family: 'Inter', sans-serif;
    min-height: 100vh;
    overflow-x: hidden;
  }

  /* Animated background */
  body::before {
    content: '';
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background:
      radial-gradient(ellipse at 20% 50%, rgba(249,115,22,0.08) 0%, transparent 50%),
      radial-gradient(ellipse at 80% 20%, rgba(6,182,212,0.06) 0%, transparent 50%),
      radial-gradient(ellipse at 50% 80%, rgba(139,92,246,0.05) 0%, transparent 50%);
    z-index: -1;
    animation: bgPulse 8s ease-in-out infinite alternate;
  }

  @keyframes bgPulse {
    0% { opacity: 0.7; }
    100% { opacity: 1; }
  }

  .container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 24px;
  }

  /* Header */
  .header {
    display: flex;
    align-items: center;
    gap: 20px;
    margin-bottom: 32px;
    padding: 24px 32px;
    background: linear-gradient(135deg, var(--card) 0%, #1a1f2e 100%);
    border: 1px solid var(--card-border);
    border-radius: 16px;
    position: relative;
    overflow: hidden;
  }

  .header::after {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, var(--accent), var(--accent2), var(--accent3));
  }

  .avatar {
    width: 72px; height: 72px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--accent), var(--accent3));
    display: flex; align-items: center; justify-content: center;
    font-size: 32px;
    box-shadow: 0 0 30px rgba(249,115,22,0.3);
    animation: avatarGlow 3s ease-in-out infinite alternate;
    flex-shrink: 0;
  }

  @keyframes avatarGlow {
    0% { box-shadow: 0 0 20px rgba(249,115,22,0.2); }
    100% { box-shadow: 0 0 40px rgba(249,115,22,0.4); }
  }

  .header-info h1 {
    font-size: 28px;
    font-weight: 700;
    background: linear-gradient(135deg, var(--accent), var(--accent2));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .header-info .subtitle {
    color: var(--text-dim);
    font-size: 14px;
    margin-top: 4px;
  }

  .status-badge {
    margin-left: auto;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 16px;
    background: rgba(16,185,129,0.1);
    border: 1px solid rgba(16,185,129,0.3);
    border-radius: 20px;
    font-size: 13px;
    color: var(--accent4);
  }

  .status-dot {
    width: 8px; height: 8px;
    border-radius: 50%;
    background: var(--accent4);
    animation: pulse 2s infinite;
  }

  @keyframes pulse {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.5; transform: scale(1.2); }
  }

  /* Stats Grid */
  .stats-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
  }

  .stat-card {
    background: var(--card);
    border: 1px solid var(--card-border);
    border-radius: 12px;
    padding: 20px;
    position: relative;
    overflow: hidden;
    transition: transform 0.2s, border-color 0.2s;
  }

  .stat-card:hover {
    transform: translateY(-2px);
    border-color: var(--accent);
  }

  .stat-card .icon {
    font-size: 24px;
    margin-bottom: 8px;
  }

  .stat-card .value {
    font-size: 32px;
    font-weight: 700;
    font-family: 'JetBrains Mono', monospace;
  }

  .stat-card .label {
    font-size: 13px;
    color: var(--text-dim);
    margin-top: 4px;
  }

  .stat-card::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 3px;
  }

  .stat-card:nth-child(1)::after { background: var(--accent); }
  .stat-card:nth-child(2)::after { background: var(--accent2); }
  .stat-card:nth-child(3)::after { background: var(--accent3); }
  .stat-card:nth-child(4)::after { background: var(--accent4); }

  .stat-card:nth-child(1) .value { color: var(--accent); }
  .stat-card:nth-child(2) .value { color: var(--accent2); }
  .stat-card:nth-child(3) .value { color: var(--accent3); }
  .stat-card:nth-child(4) .value { color: var(--accent4); }

  /* Main Grid */
  .main-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-bottom: 24px;
  }

  .panel {
    background: var(--card);
    border: 1px solid var(--card-border);
    border-radius: 12px;
    padding: 24px;
  }

  .panel-title {
    font-size: 16px;
    font-weight: 600;
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .panel-title .dot {
    width: 8px; height: 8px;
    border-radius: 50%;
  }

  /* Skills List */
  .skill-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 12px;
    border-radius: 8px;
    margin-bottom: 6px;
    background: rgba(255,255,255,0.02);
    transition: background 0.2s;
  }

  .skill-item:hover {
    background: rgba(255,255,255,0.05);
  }

  .skill-name {
    font-size: 13px;
    font-family: 'JetBrains Mono', monospace;
  }

  .skill-tag {
    font-size: 11px;
    padding: 2px 8px;
    border-radius: 10px;
    font-weight: 600;
  }

  .tag-common { background: rgba(249,115,22,0.15); color: var(--accent); }
  .tag-typescript { background: rgba(6,182,212,0.15); color: var(--accent2); }

  /* Conversation Timeline */
  .timeline-item {
    padding: 12px 16px;
    border-left: 2px solid var(--card-border);
    margin-left: 8px;
    margin-bottom: 8px;
    position: relative;
    transition: border-color 0.2s;
  }

  .timeline-item::before {
    content: '';
    position: absolute;
    left: -5px; top: 16px;
    width: 8px; height: 8px;
    border-radius: 50%;
    background: var(--accent2);
  }

  .timeline-item:hover {
    border-left-color: var(--accent2);
  }

  .timeline-role {
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 4px;
  }

  .role-user { color: var(--accent); }
  .role-assistant { color: var(--accent2); }

  .timeline-content {
    font-size: 13px;
    color: var(--text-dim);
    line-height: 1.5;
    max-height: 60px;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .timeline-time {
    font-size: 11px;
    color: var(--text-dim);
    opacity: 0.5;
    margin-top: 4px;
  }

  /* Wiki Pages */
  .wiki-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }

  .wiki-item {
    padding: 10px 12px;
    background: rgba(255,255,255,0.02);
    border-radius: 8px;
    font-size: 13px;
    font-family: 'JetBrains Mono', monospace;
    display: flex;
    align-items: center;
    gap: 8px;
    transition: background 0.2s;
  }

  .wiki-item:hover {
    background: rgba(139,92,246,0.1);
  }

  .wiki-icon { font-size: 14px; }

  /* Architecture Diagram */
  .arch-diagram {
    font-family: 'JetBrains Mono', monospace;
    font-size: 12px;
    line-height: 1.6;
    color: var(--accent2);
    background: rgba(0,0,0,0.3);
    padding: 16px;
    border-radius: 8px;
    overflow-x: auto;
    white-space: pre;
  }

  /* Memory Sessions */
  .session-card {
    padding: 16px;
    background: rgba(255,255,255,0.02);
    border-radius: 8px;
    margin-bottom: 12px;
    border: 1px solid transparent;
    transition: border-color 0.2s;
  }

  .session-card:hover {
    border-color: var(--accent3);
  }

  .session-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
  }

  .session-id {
    font-family: 'JetBrains Mono', monospace;
    font-size: 12px;
    color: var(--accent3);
  }

  .session-date {
    font-size: 11px;
    color: var(--text-dim);
  }

  .session-topics {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
  }

  .topic-tag {
    font-size: 11px;
    padding: 3px 10px;
    border-radius: 12px;
    background: rgba(139,92,246,0.1);
    color: var(--accent3);
    border: 1px solid rgba(139,92,246,0.2);
  }

  /* Full Width Panel */
  .full-width {
    grid-column: 1 / -1;
  }

  /* Responsive */
  @media (max-width: 900px) {
    .stats-grid { grid-template-columns: repeat(2, 1fr); }
    .main-grid { grid-template-columns: 1fr; }
    .wiki-grid { grid-template-columns: 1fr; }
  }

  /* Scrollbar */
  ::-webkit-scrollbar { width: 6px; }
  ::-webkit-scrollbar-track { background: var(--bg); }
  ::-webkit-scrollbar-thumb { background: var(--card-border); border-radius: 3px; }

  /* Footer */
  .footer {
    text-align: center;
    padding: 24px;
    color: var(--text-dim);
    font-size: 12px;
    border-top: 1px solid var(--card-border);
    margin-top: 24px;
  }

  .footer a { color: var(--accent); text-decoration: none; }
</style>
</head>
